from synapsekit import LLMConfig from synapsekit.llms.openai import OpenAILLM # Use a cheaper model for bulk analysis — most articles need simple classification llm = OpenAILLM( model="gpt-4o-mini", config=LLMConfig(temperature=0.1, json_mode=True), ) ANALYSIS_PROMPT = """You are a news analyst. Analyse the article below for a technology industry monitor. Extract entities, assess sentiment, and score relevance to the topic. Be conservative with relevance — score 0.8+ only when the topic is the central subject.""" async def analyse_article(article: dict) -> dict: """Analyse a single article and return enriched metadata.""" text = ( f"Topic: {article['_topic']}
" f"Title: {article['title']}
" f"Source: {article['source']['name']}

" f"{article.get('description', '')} {article.get('content', '')[:1000]}" ) analysis: ArticleAnalysis = await llm.agenerate( text, system_prompt=ANALYSIS_PROMPT, response_model=ArticleAnalysis, ) return {**article, "analysis": analysis} async def analyse_batch(articles: list[dict]) -> list[dict]: """Analyse all articles concurrently to minimise wall-clock time.""" results = await asyncio.gather(*[analyse_article(a) for a in articles]) # Filter out low-relevance articles before digest generation return [r for r in results if r["analysis"].relevance_score >= 0.5]

def deduplicate(articles: list[dict], similarity_threshold: float = 0.85) -> list[dict]: """Remove articles that cover the same event based on title similarity. A simple heuristic: if two titles share more than N words (excluding stopwords), keep only the one from the higher-reputation source. """ STOPWORDS = {"the", "a", "an", "in", "of", "and", "to", "for", "on", "is", "are", "was"} SOURCE_RANK = {"Reuters": 1, "BBC News": 2, "TechCrunch": 3} seen_tokens: list[set] = [] unique = [] for article in sorted(articles, key=lambda a: SOURCE_RANK.get(a["source"]["name"], 99)): tokens = { w.lower() for w in article["title"].split() if w.lower() not in STOPWORDS and len(w) > 3 } for seen in seen_tokens: overlap = len(tokens & seen) / max(len(tokens | seen), 1) if overlap >= similarity_threshold: break # Duplicate — skip this article else: unique.append(article) seen_tokens.append(tokens) print(f"After deduplication: {len(unique)} unique stories (removed {len(articles)-len(unique)})") return unique class DigestSection(BaseModel): topic: str headline: str summary: str articles: list[str] = Field(description="List of article URLs in this section") class DailyDigest(BaseModel): date: str headline_story: str = Field(description="The single most important story of the day") sections: list[DigestSection] notable_companies: list[str] = Field(description="Companies that appeared most frequently") notable_people: list[str] = Field(description="People who appeared most frequently") sentiment_summary: str = Field(description="Overall tone of today's news in 1-2 sentences") async def generate_digest(articles: list[dict]) -> DailyDigest: """Synthesise a daily digest from analysed articles.""" # Build a compact representation of all articles for the digest prompt article_summaries = "

".join([ f"[{a['source']['name']}] {a['title']}
" f"Relevance: {a['analysis'].relevance_score:.1f} | " f"Sentiment: {a['analysis'].sentiment}
" f"{a['analysis'].one_liner}
" f"URL: {a['url']}" for a in articles[:30] # Cap at 30 to stay within context window ]) digest_llm = OpenAILLM( model="gpt-4o", config=LLMConfig(temperature=0.2, max_tokens=2048, json_mode=True), ) digest: DailyDigest = await digest_llm.agenerate( f"Today's articles:

{article_summaries}", system_prompt=( "You are a senior analyst compiling a daily technology news digest. " "Group articles by theme, identify the most important story, and note " "which companies and people featured most prominently." ), response_model=DailyDigest, ) return digest

import json from typing import Any async def get_schema() -> str: """Return the database schema as a string the LLM can reason about.""" async with aiosqlite.connect(DATABASE_PATH) as db: db.row_factory = aiosqlite.Row cursor = await db.execute( "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name" ) tables = [row["name"] for row in await cursor.fetchall()] schema_parts = [] for table in tables: cursor = await db.execute(f"PRAGMA table_info({table})") columns = await cursor.fetchall() col_defs = ", ".join( f"{col['name']} {col['type']}{' -- PK' if col['pk'] else ''}" for col in columns ) schema_parts.append(f"Table: {table}
 Columns: {col_defs}") return "

".join(schema_parts) async def execute_query(sql: str) -> list[dict[str, Any]]: """Execute a read-only SQL query and return results as a list of dicts. Only SELECT statements are permitted — any other statement raises ValueError. This prevents the agent from accidentally running DROP or UPDATE. """ normalised = sql.strip().upper() if not normalised.startswith("SELECT"): raise ValueError( f"Only SELECT queries are allowed. Received: {sql[:60]!r}" ) async with aiosqlite.connect(DATABASE_PATH) as db: db.row_factory = aiosqlite.Row cursor = await db.execute(sql) rows = await cursor.fetchall() return [dict(row) for row in rows] def format_as_table(rows: list[dict]) -> str: """Format query results as a markdown table for readable Slack/chat display.""" if not rows: return "No results found." headers = list(rows[0].keys()) header_row = " | ".join(headers) divider_row = " | ".join("---" for _ in headers) data_rows = "
".join( " | ".join(str(row.get(h, "")) for h in headers) for row in rows ) return f"{header_row}
{divider_row}
{data_rows}"

async def run_rounds( messenger: AgentMessenger, shared: SharedState, topic: str, rounds: int, ) -> None: # The advocate opens with an initial argument opening = await messenger.send( from_agent="advocate", to_agent="advocate", # Self-addressed to generate an opening statement message=f"Make an opening argument in favor of: {topic}", ) state = await shared.get_state() state.transcript.append({"speaker": "advocate", "text": opening.text}) await shared.set_state(state) print(f"[advocate] {opening.text}
") # Alternate between critic and advocate for `rounds` exchanges for i in range(rounds): # Critic reads the last advocate message and challenges it last_advocate_msg = state.transcript[-1]["text"] critique = await messenger.send( from_agent="critic", to_agent="critic", message=( f"Topic: {topic}

" f"Critique this argument:
{last_advocate_msg}" ), ) state.transcript.append({"speaker": "critic", "text": critique.text}) await shared.set_state(state) print(f"[critic] {critique.text}
") # Advocate reads the critique and responds rebuttal = await messenger.send( from_agent="advocate", to_agent="advocate", message=( f"Topic: {topic}

" f"Respond to this critique:
{critique.text}" ), ) state.transcript.append({"speaker": "advocate", "text": rebuttal.text}) await shared.set_state(state) print(f"[advocate] {rebuttal.text}
") async def synthesize(messenger: AgentMessenger, shared: SharedState) -> None: state = await shared.get_state() # Format the transcript for the synthesizer formatted = "

".join( f"{entry['speaker'].upper()}: {entry['text']}" for entry in state.transcript ) result = await messenger.send( from_agent="synthesizer", to_agent="synthesizer", message=f"Synthesize the following debate:

{formatted}", ) state.synthesis = result.text await shared.set_state(state) print(f"
[synthesizer] {result.text}")

